    def __init__(self, tree, path=()):
        self._tree = tree
        self._path = path

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, ())

    def _focus(self):
        node = self._tree
        for step in self._path:
            node = node[step]
        return node

    def _replace_focus(self, focus):
        if not self._path:
            return focus
        step, rest = self._path[0], self._path[1:]
        node = dict(self._tree)
        node[step] = Zipper(self._tree[step], rest)._replace_focus(focus)
        return node

    def _with_focus(self, focus):
        return Zipper(self._replace_focus(focus), self._path)

    def value(self):
        return self._focus()["value"]

    def set_value(self, value):
        focus = dict(self._focus())
        focus["value"] = value
        return self._with_focus(focus)

    def left(self):
        if self._focus()["left"] is None:
            return None
        return Zipper(self._tree, self._path + ("left",))

    def set_left(self, subtree):
        focus = dict(self._focus())
        focus["left"] = subtree
        return self._with_focus(focus)

    def right(self):
        if self._focus()["right"] is None:
            return None
        return Zipper(self._tree, self._path + ("right",))

    def set_right(self, subtree):
        focus = dict(self._focus())
        focus["right"] = subtree
        return self._with_focus(focus)

    def up(self):
        if not self._path:
            return None
        return Zipper(self._tree, self._path[:-1])

    def to_tree(self):
